const $ = selector => document.querySelector(selector);
const h = value => String(value).replace(/[&<>'"]/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));
const t = key => I18N[state.language]?.[key] || I18N.en[key] || key;
const lt = values => values[state.language] || values.en || values.ru;
const passwordIcon = visible => visible
  ? '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 3l18 18"/><path d="M10.6 10.7a2 2 0 0 0 2.7 2.7"/><path d="M9.9 4.2A10.7 10.7 0 0 1 12 4c5.5 0 9 5.2 9 8a9.8 9.8 0 0 1-2 3.7M6.6 6.6C4.3 8.1 3 10.4 3 12c0 2.8 3.5 8 9 8 1.5 0 2.8-.4 4-1"/></svg>'
  : '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M2.5 12s3.5-7 9.5-7 9.5 7 9.5 7-3.5 7-9.5 7-9.5-7-9.5-7Z"/><circle cx="12" cy="12" r="3"/></svg>';
function setPasswordToggle(button, visible=false) {
  if(!button) return;
  button.innerHTML=passwordIcon(visible);
  const label=t(visible?'hidePassword':'showPassword');
  button.setAttribute('aria-label',label);
  button.title=label;
  button.setAttribute('aria-pressed',String(visible));
}
const localizeApiError = (message, fallbackKey) => ({
  'Текущий пароль указан неверно':'wrongCurrentPassword',
  'Неверный e-mail или пароль':'invalidCredentials'
}[message] ? t({
  'Текущий пароль указан неверно':'wrongCurrentPassword',
  'Неверный e-mail или пароль':'invalidCredentials'
}[message]) : message || t(fallbackKey));

async function apiFetch(url, options={}) {
  const method=String(options.method||'GET').toUpperCase();
  const headers=new Headers(options.headers||{});
  if(!['GET','HEAD','OPTIONS'].includes(method)&&state.csrfToken) headers.set('X-CSRF-Token',state.csrfToken);
  const response=await fetch(url,{...options,method,headers,credentials:'same-origin'});
  if(response.status===401&&state.apiMode) showAuthGate(t('sessionEnded'));
  return response;
}

function setSession(data) {
  state.user=data.user;
  state.organization=data.organization;
  state.csrfToken=data.csrfToken;
  $('#currentUser').textContent=data.user.email;
  $('#currentOrganization').textContent=data.organization.name;
  $('#connectAllegro').href=`/api/auth/allegro?csrf=${encodeURIComponent(state.csrfToken)}`;
  $('#connectAllegroCard').href=$('#connectAllegro').href;
  $('#profileForm').elements.organizationName.value=data.organization.name;
  $('#profileForm').elements.email.value=data.user.email;
}

function applyLanguage(language=state.language) {
  state.language=SUPPORTED_LANGUAGES.includes(language)?language:'pl';
  localStorage.setItem('profitpilot-language',state.language);
  document.documentElement.lang=state.language;
  $('#languageSelect').value=state.language;
  money=new Intl.NumberFormat(localeByLanguage[state.language],{style:'currency',currency:'PLN',maximumFractionDigits:0});
  moneyExact=new Intl.NumberFormat(localeByLanguage[state.language],{style:'currency',currency:'PLN',minimumFractionDigits:2});
  document.querySelectorAll('[data-i18n]').forEach(element=>{element.textContent=t(element.dataset.i18n);});
  document.querySelectorAll('[data-i18n-placeholder]').forEach(element=>{element.placeholder=t(element.dataset.i18nPlaceholder);});
  document.querySelectorAll('[data-i18n-aria]').forEach(element=>{element.setAttribute('aria-label',t(element.dataset.i18nAria));});
  document.querySelectorAll('[data-password-toggle]').forEach(button=>{const input=button.previousElementSibling;setPasswordToggle(button,input?.type==='text');});
  updateAuthUi();
  setView(state.view);
  renderAll();
  if(state.apiMode) { refreshIntegration(); loadSessions(); }
}

function showAuthGate(message='') {
  state.user=null; state.organization=null; state.csrfToken=null;
  resetAuthUi();
  $('#authGate').hidden=false; $('#appSidebar').hidden=true; $('#appMain').hidden=true;
  $('#authError').textContent=message;
}

function showApplication() {
  $('#authGate').hidden=true; $('#appSidebar').hidden=false; $('#appMain').hidden=false;
}

function loadProducts() {
  try { return JSON.parse(localStorage.getItem('profitpilot-products')) || structuredClone(DEMO_PRODUCTS); }
  catch { return structuredClone(DEMO_PRODUCTS); }
}

function calculate(product) {
  const revenue = product.units * product.price;
  const costsPerUnit = product.cost + product.commission + product.ads + product.shipping + product.returns;
  const costs = product.units * costsPerUnit;
  const profit = revenue - costs;
  const margin = revenue ? profit / revenue * 100 : 0;
  return { ...product, revenue, costs, profit, margin, profitPerUnit: product.price - costsPerUnit };
}

function scaledProducts() {
  const scale = state.period / 30;
  return state.products.map(p => calculate({...p, units: Math.max(1, Math.round(p.units * scale))}));
}

function getStatus(p) { return p.margin < 0 ? 'loss' : p.margin < 8 ? 'risk' : 'healthy'; }
function statusLabel(status) { return t(status === 'loss' ? 'statusLoss' : status === 'risk' ? 'statusRisk' : 'statusHealthy'); }
function pluralRu(number, one, few, many) { const n=Math.abs(number)%100; const n1=n%10; return n>10&&n<20?many:n1>1&&n1<5?few:n1===1?one:many; }

function recommendationFor(p) {
  const status = getStatus(p);
  if (status === 'healthy') return null;
  const targetMargin = .15;
  const costsPerUnit = p.cost + p.commission + p.ads + p.shipping + p.returns;
  const targetPrice = costsPerUnit / (1 - targetMargin);
  const adShare = p.ads / p.price;
  const marketPrice=Number(p.marketPrice||0); const marketAge=p.marketUpdatedAt?Date.now()-new Date(p.marketUpdatedAt).getTime():Infinity;
  const marketFresh=marketPrice>0&&Number.isFinite(marketAge)&&marketAge<=72*60*60*1000; const marketCeiling=marketFresh?marketPrice*.99:0;
  if (adShare > .09) {
    const saving = p.ads * .3;
    const marketLabel=marketFresh?moneyExact.format(marketPrice):lt({ru:'нет свежих данных',pl:'brak aktualnych danych',en:'no fresh data',uk:'немає свіжих даних',cs:'bez aktuálních dat',sk:'bez aktuálnych údajov',hu:'nincs friss adat'});
    return {sku:p.sku,title:lt({ru:'Снизить расходы на рекламу',pl:'Obniż wydatki na reklamę',en:'Reduce advertising costs',uk:'Знизити витрати на рекламу',cs:'Snížit náklady na reklamu',sk:'Znížiť náklady na reklamu',hu:'Hirdetési költségek csökkentése'}),description:lt({ru:`${p.name}: реклама забирает ${(adShare*100).toFixed(1)}% цены. Сократите ставку примерно на 30%. Рыночный ориентир: ${marketLabel}.`,pl:`${p.name}: reklama pochłania ${(adShare*100).toFixed(1)}% ceny. Zmniejsz stawkę o około 30%. Punkt odniesienia: ${marketLabel}.`,en:`${p.name}: advertising takes ${(adShare*100).toFixed(1)}% of the price. Reduce the bid by about 30%. Market benchmark: ${marketLabel}.`,uk:`${p.name}: реклама забирає ${(adShare*100).toFixed(1)}% ціни. Зменште ставку приблизно на 30%. Ринковий орієнтир: ${marketLabel}.`,cs:`${p.name}: reklama tvoří ${(adShare*100).toFixed(1)}% ceny. Snižte nabídku přibližně o 30 %. Tržní srovnání: ${marketLabel}.`,sk:`${p.name}: reklama tvorí ${(adShare*100).toFixed(1)}% ceny. Znížte ponuku približne o 30 %. Trhové porovnanie: ${marketLabel}.`,hu:`${p.name}: a hirdetés az ár ${(adShare*100).toFixed(1)}%-át viszi el. Csökkentse a licitet körülbelül 30%-kal. Piaci viszonyítás: ${marketLabel}.`}),action:lt({ru:'Проверить рекламу',pl:'Sprawdź reklamę',en:'Review advertising',uk:'Перевірити рекламу',cs:'Zkontrolovat reklamu',sk:'Skontrolovať reklamu',hu:'Hirdetés ellenőrzése'}),potential:saving*p.units,type:status==='loss'?'danger':'warning',kind:'ads',channel:p.channel,marketPrice:marketFresh?marketPrice:null};
  }
  if(!marketFresh) return {sku:p.sku,title:lt({ru:`Обновить цену рынка для ${p.name}`,pl:`Zaktualizuj cenę rynkową dla ${p.name}`,en:`Update the market price for ${p.name}`,uk:`Оновіть ринкову ціну для ${p.name}`,cs:`Aktualizujte tržní cenu pro ${p.name}`,sk:`Aktualizujte trhovú cenu pre ${p.name}`,hu:`Frissítse a(z) ${p.name} piaci árát`}),description:marketPrice?lt({ru:`Последний ориентир ${moneyExact.format(marketPrice)} устарел. До обновления ProfitPilot не будет советовать повышение цены.`,pl:`Ostatni punkt odniesienia ${moneyExact.format(marketPrice)} jest nieaktualny. Do czasu aktualizacji ProfitPilot nie zaleci podwyżki ceny.`,en:`The last benchmark of ${moneyExact.format(marketPrice)} is outdated. ProfitPilot will not recommend a price increase until it is updated.`,uk:`Останній орієнтир ${moneyExact.format(marketPrice)} застарів. До оновлення ProfitPilot не радитиме підвищення ціни.`,cs:`Poslední srovnání ${moneyExact.format(marketPrice)} je zastaralé. ProfitPilot do aktualizace nedoporučí zvýšení ceny.`,sk:`Posledné porovnanie ${moneyExact.format(marketPrice)} je zastarané. ProfitPilot do aktualizácie neodporučí zvýšenie ceny.`,hu:`A legutóbbi ${moneyExact.format(marketPrice)} viszonyítás elavult. Frissítésig a ProfitPilot nem javasol áremelést.`}):lt({ru:'Нет свежей цены сопоставимых предложений. Повышение цены заблокировано, пока рынок не проверен.',pl:'Brak aktualnej ceny porównywalnych ofert. Podwyżka ceny jest zablokowana do czasu sprawdzenia rynku.',en:'There is no fresh price for comparable offers. Price increases are blocked until the market is checked.',uk:'Немає свіжої ціни порівнянних пропозицій. Підвищення ціни заблоковано до перевірки ринку.',cs:'Chybí aktuální cena srovnatelných nabídek. Zvýšení ceny je blokováno do kontroly trhu.',sk:'Chýba aktuálna cena porovnateľných ponúk. Zvýšenie ceny je blokované do kontroly trhu.',hu:'Nincs friss ár az összehasonlítható ajánlatokhoz. Az áremelés a piac ellenőrzéséig blokkolva van.'}),action:lt({ru:'Указать цену рынка',pl:'Ustaw cenę rynkową',en:'Set market price',uk:'Вказати ринкову ціну',cs:'Nastavit tržní cenu',sk:'Nastaviť trhovú cenu',hu:'Piaci ár megadása'}),potential:0,requiresData:true,type:'info',kind:marketPrice?'market_stale':'market_missing',channel:p.channel,marketPrice:marketPrice||null};
  if(targetPrice<=marketCeiling&&targetPrice>p.price) return {sku:p.sku,title:lt({ru:`Осторожно поднять цену ${p.name}`,pl:`Ostrożnie podnieś cenę ${p.name}`,en:`Carefully raise the price of ${p.name}`,uk:`Обережно підвищити ціну ${p.name}`,cs:`Opatrně zvyšte cenu ${p.name}`,sk:`Opatrne zvýšte cenu ${p.name}`,hu:`Óvatosan emelje a(z) ${p.name} árát`}),description:lt({ru:`Цена ${moneyExact.format(targetPrice)} даёт маржу 15% и остаётся ниже рыночного ориентира ${moneyExact.format(marketPrice)}. Рекомендуемый потолок: ${moneyExact.format(marketCeiling)}.`,pl:`Cena ${moneyExact.format(targetPrice)} daje marżę 15% i pozostaje poniżej rynku ${moneyExact.format(marketPrice)}. Zalecany limit: ${moneyExact.format(marketCeiling)}.`,en:`A price of ${moneyExact.format(targetPrice)} gives a 15% margin and stays below the market benchmark of ${moneyExact.format(marketPrice)}. Recommended ceiling: ${moneyExact.format(marketCeiling)}.`,uk:`Ціна ${moneyExact.format(targetPrice)} дає маржу 15% і залишається нижче ринку ${moneyExact.format(marketPrice)}. Рекомендована межа: ${moneyExact.format(marketCeiling)}.`,cs:`Cena ${moneyExact.format(targetPrice)} dává marži 15 % a zůstává pod tržní hodnotou ${moneyExact.format(marketPrice)}. Doporučený strop: ${moneyExact.format(marketCeiling)}.`,sk:`Cena ${moneyExact.format(targetPrice)} dáva maržu 15 % a zostáva pod trhovou hodnotou ${moneyExact.format(marketPrice)}. Odporúčaný strop: ${moneyExact.format(marketCeiling)}.`,hu:`A ${moneyExact.format(targetPrice)} ár 15%-os árrést ad, és a ${moneyExact.format(marketPrice)} piaci érték alatt marad. Javasolt plafon: ${moneyExact.format(marketCeiling)}.`}),action:`${lt({ru:'Цена',pl:'Cena',en:'Price',uk:'Ціна',cs:'Cena',sk:'Cena',hu:'Ár'})} → ${moneyExact.format(targetPrice)}`,potential:(targetPrice-p.price)*p.units,type:status==='loss'?'danger':'warning',kind:'market_safe_price',channel:p.channel,marketPrice,marketCeiling};
  const viableCosts=marketCeiling*(1-targetMargin); const reduction=Math.max(0,costsPerUnit-viableCosts);
  return {sku:p.sku,title:lt({ru:'Снижать затраты, а не повышать цену',pl:'Obniż koszty zamiast podnosić cenę',en:'Reduce costs instead of raising the price',uk:'Знижуйте витрати, а не підвищуйте ціну',cs:'Snižte náklady místo zvýšení ceny',sk:'Znížte náklady namiesto zvýšenia ceny',hu:'Csökkentse a költségeket áremelés helyett'}),description:lt({ru:`Для маржи 15% нужна цена ${moneyExact.format(targetPrice)}, но рынок около ${moneyExact.format(marketPrice)}. Сократите затраты минимум на ${moneyExact.format(reduction)} с единицы или пересмотрите товар.`,pl:`Marża 15% wymaga ceny ${moneyExact.format(targetPrice)}, ale rynek to około ${moneyExact.format(marketPrice)}. Obniż koszty o co najmniej ${moneyExact.format(reduction)} na sztuce lub zrewiduj produkt.`,en:`A 15% margin requires a price of ${moneyExact.format(targetPrice)}, but the market is around ${moneyExact.format(marketPrice)}. Cut costs by at least ${moneyExact.format(reduction)} per unit or reconsider the product.`,uk:`Для маржі 15% потрібна ціна ${moneyExact.format(targetPrice)}, але ринок близько ${moneyExact.format(marketPrice)}. Скоротіть витрати щонайменше на ${moneyExact.format(reduction)} з одиниці або перегляньте товар.`,cs:`Marže 15 % vyžaduje cenu ${moneyExact.format(targetPrice)}, ale trh je kolem ${moneyExact.format(marketPrice)}. Snižte náklady alespoň o ${moneyExact.format(reduction)} na kus nebo produkt přehodnoťte.`,sk:`Marža 15 % vyžaduje cenu ${moneyExact.format(targetPrice)}, ale trh je okolo ${moneyExact.format(marketPrice)}. Znížte náklady aspoň o ${moneyExact.format(reduction)} na kus alebo produkt prehodnoťte.`,hu:`A 15%-os árréshez ${moneyExact.format(targetPrice)} ár kellene, de a piac körülbelül ${moneyExact.format(marketPrice)}. Csökkentse a költséget legalább ${moneyExact.format(reduction)} összeggel darabonként, vagy vizsgálja felül a terméket.`}),action:lt({ru:'Разобрать затраты',pl:'Przeanalizuj koszty',en:'Review costs',uk:'Розібрати витрати',cs:'Prověřit náklady',sk:'Preveriť náklady',hu:'Költségek elemzése'}),potential:reduction*p.units,type:status==='loss'?'danger':'warning',kind:'required_savings',channel:p.channel,marketPrice,marketCeiling};
}

function recommendations() { return scaledProducts().map(recommendationFor).filter(Boolean).sort((a,b) => b.potential-a.potential); }

function renderMetrics() {
  const products = scaledProducts();
  const total = products.reduce((a,p) => ({ revenue:a.revenue+p.revenue, profit:a.profit+p.profit, units:a.units+p.units }), {revenue:0,profit:0,units:0});
  const margin = total.revenue ? total.profit/total.revenue*100 : 0;
  const cards = [
    [t('revenue'), money.format(total.revenue), t('previousRevenue'), false],
    [t('netProfit'), money.format(total.profit), t(total.profit >= 0 ? 'previousProfit' : 'attention'), total.profit < 0],
    [t('margin'), `${margin.toFixed(1)}%`, t(margin >= 15 ? 'healthyRange' : 'belowTarget'), margin < 15],
    [t('unitsSold'), total.units.toLocaleString(localeByLanguage[state.language]), lt({ru:`${products.length} активных SKU`,pl:`${products.length} aktywnych SKU`,en:`${products.length} active SKUs`,uk:`${products.length} активних SKU`,cs:`${products.length} aktivních SKU`,sk:`${products.length} aktívnych SKU`,hu:`${products.length} aktív SKU`}), false]
  ];
  $('#metrics').innerHTML = cards.map(c => `<article class="metric-card"><span class="metric-label">${c[0]}</span><strong class="metric-value">${c[1]}</strong><span class="metric-change ${c[3]?'negative':''}">${c[2]}</span></article>`).join('');
}

function renderChart() {
  const products = scaledProducts();
  const totalRevenue = products.reduce((a,p)=>a+p.revenue,0);
  const totalProfit = products.reduce((a,p)=>a+p.profit,0);
  const labels = state.period === 7 ? lt({ru:['Пн','Вт','Ср','Чт','Пт','Сб','Вс'],pl:['Pn','Wt','Śr','Cz','Pt','So','Nd'],en:['Mon','Tue','Wed','Thu','Fri','Sat','Sun'],uk:['Пн','Вт','Ср','Чт','Пт','Сб','Нд'],cs:['Po','Út','St','Čt','Pá','So','Ne'],sk:['Po','Ut','St','Št','Pi','So','Ne'],hu:['H','K','Sze','Cs','P','Szo','V']}) : ['1','5','10','15','20','25','30'];
  const factors = [.10,.135,.12,.16,.145,.18,.16];
  const revenues = factors.map((f,i)=>totalRevenue*f*(.92 + ((i*7)%5)/20));
  const profits = factors.map((f,i)=>totalProfit*f*(.86 + ((i*3)%4)/20));
  const max = Math.max(...revenues, 1) * 1.08;
  const w=700,h=210,pad=28;
  const points = values => values.map((v,i)=>`${pad+i*((w-pad*2)/(values.length-1))},${h-pad-(v/max)*(h-pad*2)}`).join(' ');
  const area = `${pad},${h-pad} ${points(revenues)} ${w-pad},${h-pad}`;
  const grid = [0,.25,.5,.75,1].map(v=>`<line class="grid-line" x1="${pad}" y1="${h-pad-v*(h-pad*2)}" x2="${w-pad}" y2="${h-pad-v*(h-pad*2)}"/>`).join('');
  const xlabels = labels.map((l,i)=>`<text class="axis-label" x="${pad+i*((w-pad*2)/(labels.length-1))}" y="${h-4}" text-anchor="middle">${l}</text>`).join('');
  $('#profitChart').innerHTML = `<svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#bdd4c6" stop-opacity=".55"/><stop offset="1" stop-color="#bdd4c6" stop-opacity="0"/></linearGradient></defs>${grid}<polygon points="${area}" fill="url(#area)"/><polyline points="${points(revenues)}" fill="none" stroke="#9fbbaa" stroke-width="3"/><polyline points="${points(profits)}" fill="none" stroke="#236b4c" stroke-width="3"/>${xlabels}</svg>`;
}

function renderHealth() {
  const products=scaledProducts(); const counts={healthy:0,risk:0,loss:0}; products.forEach(p=>counts[getStatus(p)]++);
  const n=products.length||1; const green=counts.healthy/n*100; const amber=(counts.healthy+counts.risk)/n*100;
  $('#healthChart').style.background=`conic-gradient(var(--green) 0 ${green}%, var(--amber) ${green}% ${amber}%, var(--red) ${amber}% 100%)`;
  $('#healthChart').innerHTML=`<div class="health-center"><strong>${products.length}</strong><span>${h(t('productsWord'))}</span></div>`;
  const rows=[['#236b4c',t('healthyMargin'),counts.healthy],['#d58b20',t('lowMargin'),counts.risk],['#bd4b42',t('lossMaking'),counts.loss]];
  $('#healthLegend').innerHTML=rows.map(r=>`<div class="health-row"><i style="background:${r[0]}"></i><span>${r[1]}</span><b>${r[2]}</b></div>`).join('');
}

