$('#passwordForm').addEventListener('submit',async event=>{
  event.preventDefault();const form=event.currentTarget;const button=form.querySelector('button[type="submit"]');button.disabled=true;
  try { const payload=Object.fromEntries(new FormData(form));const response=await apiFetch('/api/security/password',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const result=await response.json();if(!response.ok)throw new Error(result.error);form.reset();document.querySelectorAll('#passwordForm input[type="text"]').forEach(input=>{input.type='password';});document.querySelectorAll('#passwordForm [data-password-toggle]').forEach(button=>setPasswordToggle(button,false));await loadSessions();showToast(lt({ru:'Пароль обновлён. Остальные сессии завершены.',pl:'Hasło zostało zmienione. Pozostałe sesje zakończono.',en:'Password updated. Other sessions ended.',uk:'Пароль оновлено. Інші сесії завершено.',cs:'Heslo bylo změněno. Ostatní relace byly ukončeny.',sk:'Heslo bolo zmenené. Ostatné relácie boli ukončené.',hu:'A jelszó frissítve. A többi munkamenet lezárva.'})); }
  catch(error){showToast(localizeApiError(error.message,'passwordUpdateError'));}finally{button.disabled=false;}
});

$('#revokeSessions').addEventListener('click',async()=>{try{const response=await apiFetch('/api/security/sessions',{method:'DELETE'});const result=await response.json();if(!response.ok)throw new Error(result.error);await loadSessions();showToast(`${t('sessionsEnded')}: ${result.revoked}`);}catch(error){showToast(error.message||t('sessionsEndError'));}});

let authMode='login';
function resetPasswordControls(scope=document) {
  scope.querySelectorAll('input[type="text"][autocomplete*="password"]').forEach(input=>{input.type='password';});
  scope.querySelectorAll('[data-password-toggle]').forEach(button=>setPasswordToggle(button,false));
}
function updateAuthUi() {
  const registering=authMode==='register';
  $('#loginForm').hidden=registering;
  $('#registerForm').hidden=!registering;
  $('#authTitle').textContent=t(registering?'authRegisterTitle':'authLoginTitle');
  $('#toggleAuthMode').textContent=t(registering?'switchToLogin':'switchToRegister');
}
function resetAuthUi() {
  authMode='login';
  $('#loginForm').reset();
  $('#registerForm').reset();
  resetPasswordControls($('#authGate'));
  updateAuthUi();
}
$('#toggleAuthMode').addEventListener('click',()=>{
  authMode=authMode==='login'?'register':'login';
  resetPasswordControls($('#authGate'));
  updateAuthUi();
  $('#authError').textContent='';
});

async function submitAuth(form,endpoint) {
  $('#authError').textContent='';
  const button=form.querySelector('button[type="submit"]');
  button.disabled=true;
  try {
    const payload=Object.fromEntries(new FormData(form));
    const response=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify(payload)});
    const result=await response.json();
    if(!response.ok) throw new Error(localizeApiError(result.error,'invalidCredentials'));
    state.apiMode=true;
    setSession(result);
    showApplication();
    await refreshFromServer();
    await refreshIntegration();
    form.reset();
  } catch(error) { $('#authError').textContent=error.message; }
  finally { button.disabled=false; }
}

$('#loginForm').addEventListener('submit',event=>{event.preventDefault();submitAuth(event.currentTarget,'/api/auth/login');});
$('#registerForm').addEventListener('submit',event=>{event.preventDefault();submitAuth(event.currentTarget,'/api/auth/register');});
$('#logoutButton').addEventListener('click',async()=>{
  try { await apiFetch('/api/auth/logout',{method:'POST'}); }
  finally { state.apiMode=true; showAuthGate(t('loggedOut')); }
});

async function initialize() {
  applyLanguage(initialLanguage);
  try {
    const health=await fetch('/api/health',{cache:'no-store'});
    if(!health.ok) throw new Error();
    state.apiMode=true;
    const sessionResponse=await fetch('/api/auth/me',{cache:'no-store',credentials:'same-origin'});
    if(sessionResponse.status===401) { showAuthGate(); return; }
    const session=await sessionResponse.json();
    if(!sessionResponse.ok) throw new Error(session.error||t('sessionCheckError'));
    setSession(session);
    showApplication();
    await refreshFromServer();
    await refreshIntegration();
    await loadSessions();
  } catch {
    state.apiMode=false;
    showApplication();
    $('#integrationTitle').textContent=t('demoMode');
    $('#integrationText').textContent=t('browserStorage');
    $('#integrationDot').classList.add('offline');
  }
  const integration=new URLSearchParams(location.search).get('integration');
  if(integration==='connected') showToast(t('allegroConnectedToast'));
  if(integration==='error') showToast(t('allegroConnectionError'));
}

initialize();
